struct config7 : nnet::gemm_config {
    static const unsigned n_in = 16;
    static const unsigned n_out = 16;
    static const unsigned n_patches = 8;
    static const unsigned gemm_m = 8;
    static const unsigned gemm_k = 16;
    static const unsigned gemm_n = 16;
    static const unsigned gemm_ip_id = 7;
    static const bool transpose_weights = true;
    // Microarchitecture knobs consumed by the generic (behavioral-HLS) GEMM core:
    // row-loop pipeline II and the multiplier ALLOCATION cap (mirrors nnet_dense_*).
    static const unsigned reuse_factor = 1;
    static const unsigned multiplier_limit = 256;
    typedef gemm_before_weight_t weight_t;
    typedef gemm_before_bias_t bias_t;
    typedef gemm_before_accum_t accum_t;
    template<class x_T, class y_T>
    using product = nnet::product::mult<x_T, y_T>;
    static const bool weights_row_major = false;
    typedef nnet::array<weight_t, gemm_k> weight_beat_t;
    static weight_beat_t* gemm_weight_beats() { return weight7_gemm_cols; }
    typedef weight_beat_t weight_col_t;
    static weight_col_t* gemm_weight_cols() { return weight7_gemm_cols; }
    static bias_t* gemm_bias() { return bias7; }
};

